INSERT INTO fleet_workspace_repository_refs (row_id, workspace_id, ordinal, reference_kind, normalized_origin, service_id, common_directory, created_at, updated_at) VALUES (?1, ?2, CAST(?3 AS INTEGER), ?4, ?5, ?6, ?7, CAST(?8 AS INTEGER), CAST(?8 AS INTEGER)) ON CONFLICT(workspace_id,ordinal) DO UPDATE SET reference_kind=excluded.reference_kind, normalized_origin=excluded.normalized_origin, service_id=excluded.service_id, common_directory=excluded.common_directory, updated_at=excluded.updated_at WHERE reference_kind IS NOT excluded.reference_kind OR normalized_origin IS NOT excluded.normalized_origin OR service_id IS NOT excluded.service_id OR common_directory IS NOT excluded.common_directory;
